// Config — настройки. Меняйте значения справа от двоеточия.
return [{ json: {
  "timezone": "Europe/Kyiv",
  "locale": "ru-RU",
  "sheets_api_base": "https://sheets.googleapis.com/v4",
  "spreadsheet_id": "REPLACE_WITH_SPREADSHEET_ID",
  "sheet_name": "Leads",
  "notify_chat_id": "REPLACE_WITH_CHAT_ID",
  "hot_threshold": 4,
  "report_chat_id": ""
} }];

// Daily Report — yesterday's leads in numbers, and who is still waiting.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// Column order of the Leads sheet. The sheet may start empty: the header is written with the first lead.
const COLUMNS = ['id', 'created_at', 'source', 'form', 'name', 'phone', 'email', 'message', 'utm_source', 'utm_medium', 'utm_campaign', 'page',
  'score', 'intent', 'summary', 'status', 'owner', 'touches', 'last_touch_at', 'reminded_level', 'notes'];
const colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };
const LAST = colLetter(COLUMNS.length - 1);
const rows = $input.first().json.values || [];
const now = nowMs();
const yesterday = localParts(now - 24 * 60 * MIN).date;
const at = (row, c) => row[COLUMNS.indexOf(c)] || '';
const data = rows.length && rows[0][0] === 'id' ? rows.slice(1) : [];
const made = data.filter((r) => { const t = Date.parse(at(r, 'created_at')); return !isNaN(t) && localParts(t).date === yesterday; });
const real = made.filter((r) => at(r, 'status') !== 'spam');
const count = (list, key) => { const out = {}; for (const r of list) { const k = at(r, key) || '—'; out[k] = (out[k] || 0) + 1; } return Object.entries(out).sort((a, b) => b[1] - a[1]); };
const hot = real.filter((r) => Number(at(r, 'score')) >= (cfg.hot_threshold || 4)).length;
const repeats = data.filter((r) => { const t = Date.parse(at(r, 'last_touch_at')); return Number(at(r, 'touches')) > 1 && !isNaN(t) && localParts(t).date === yesterday; }).length;
const waiting = data.filter((r) => at(r, 'status') === 'new')
  .map((r) => ({ name: at(r, 'name') || '—', contact: at(r, 'phone') || at(r, 'email'), since: Date.parse(at(r, 'created_at')) }))
  .filter((r) => !isNaN(r.since)).sort((a, b) => a.since - b.since);

const lines = [`Заявки за ${yesterday}`, `Новых: ${real.length}${hot ? `, из них горячих: ${hot}` : ''}`];
if (repeats) lines.push(`Повторных обращений: ${repeats}`);
if (made.length - real.length) lines.push(`Спам отсеян: ${made.length - real.length}`);
if (real.length) lines.push('', 'Источники:', ...count(real, 'source').map(([k, v]) => `• ${k}: ${v}`));
const campaigns = count(real.filter((r) => at(r, 'utm_campaign')), 'utm_campaign');
if (campaigns.length) lines.push('', 'Кампании:', ...campaigns.slice(0, 5).map(([k, v]) => `• ${k}: ${v}`));
lines.push('', waiting.length ? `Ждут ответа: ${waiting.length}` : 'Все заявки разобраны.');
for (const w of waiting.slice(0, 5)) lines.push(`• ${w.name}, ${w.contact}, с ${localText(w.since)}`);
return [{ json: { chat_id: cfg.report_chat_id || cfg.notify_chat_id, text: lines.join('\n') } }];
